from collections import deque


def orangesRotting(grid):
    m, n = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                q.append((i, j))
            elif grid[i][j] == 1:
                fresh += 1

    if fresh == 0:
        return 0

    minutes = 0
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q and fresh > 0:
        minutes += 1
        for _ in range(len(q)):        # 按层处理 = 一分钟
            i, j = q.popleft()
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    fresh -= 1
                    grid[ni][nj] = 2
                    q.append((ni, nj))

    return minutes if fresh == 0 else -1

