def dailyTemperatures(temperatures):
    n = len(temperatures)
    res = [0] * n
    stack = []                     # 单调递减栈，存索引

    for i in range(n):
        while stack and temperatures[stack[-1]] < temperatures[i]:
            idx = stack.pop()
            res[idx] = i - idx
        stack.append(i)

    return res

