def generateParenthesis(n):
    res = []

    def backtrack(left, right, path):
        if left == n and right == n:
            res.append(path)
            return
        if left < n:
            backtrack(left + 1, right, path + '(')
        if right < left:
            backtrack(left, right + 1, path + ')')

    backtrack(0, 0, '')
    return res

