def findMin(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = left + (right - left) // 2
        if nums[mid] > nums[right]:
            left = mid + 1          # mid 在大段，最小值在右半
        else:
            right = mid             # mid 在小段（含 mid）

    return nums[left]

